foreach ($this->participants as $participant) $participantNames[(int) $participant->id] = (string) $participant->display_name;
$phaseDefinitions = [];
foreach ($this->profile['match']['score']['segment_types'] ?? [] as $segment) if (is_array($segment) && is_string($segment['code'] ?? null)) $phaseDefinitions[$segment['code']] = (string) ($segment['name_key'] ?? $segment['code']);
?>
