				<div class="col-md-3"><label class="form-label" for="match-event-phase"><?php echo Text::_('COM_JOOMLEAGUE_FIELD_PHASE_LABEL'); ?></label><select class="form-select" id="match-event-phase" name="phase_code"><option value=""><?php echo Text::_('JNONE'); ?></option><?php foreach ($phaseDefinitions as $code => $nameKey) : ?><option value="<?php echo $this->escape($code); ?>"><?php echo Text::_($nameKey); ?></option><?php endforeach; ?></select></div>
