				<div class="col-md-3"><label class="form-label" for="match-event-clock-unit"><?php echo Text::_('COM_JOOMLEAGUE_FIELD_CLOCK_UNIT_LABEL'); ?></label><input class="form-control" id="match-event-clock-unit" name="clock_unit" placeholder="<?php echo Text::_('COM_JOOMLEAGUE_MATCHEVENTS_CLOCK_UNIT_PLACEHOLDER'); ?>"></div>
