				<div class="col-lg-4"><label class="form-label" for="match-event-occurred"><?php echo Text::_('COM_JOOMLEAGUE_FIELD_OCCURRED_AT_LABEL'); ?></label><input class="form-control" type="datetime-local" id="match-event-occurred" name="occurred_at"><div class="form-text"><?php echo Text::_('COM_JOOMLEAGUE_MATCHEVENTS_OCCURRED_AT_DESC'); ?></div></div>
