				<div class="col-lg-6"><label class="form-label" for="match-event-text"><?php echo Text::_('COM_JOOMLEAGUE_FIELD_TEXT_VALUE_LABEL'); ?></label><input class="form-control" id="match-event-text" name="text_value" maxlength="255"></div>
