			<button class="btn btn-success mt-3" type="submit" name="task" value="matchevents.add"><span class="icon-plus" aria-hidden="true"></span> <?php echo Text::_('COM_JOOMLEAGUE_MATCHEVENTS_ADD'); ?></button>
