		<?php foreach ($this->events as $event) : ?><tr><td><input class="form-check-input" type="checkbox" name="cid[]" value="<?php echo (int) $event->id; ?>" aria-label="<?php echo Text::_('JGLOBAL_SELECTION'); ?>"></td><td><?php echo (int) $event->sequence_number; ?></td><th scope="row"><?php echo Text::_($event->event_name_key); ?></th><td><?php echo $this->escape($participantNames[(int) $event->match_participant_id] ?? Text::_('JNONE')); ?></td><td><?php echo $this->escape($event->primary_name_snapshot ?: ($event->actor_name_snapshot ?: Text::_('JNONE'))); ?><?php if ($event->secondary_name_snapshot) : ?><div class="small text-body-secondary"><?php echo $this->escape($event->secondary_name_snapshot); ?></div><?php endif; ?></td><td><?php echo $this->escape($event->phase_code ?: Text::_('JNONE')); ?><?php if ($event->phase_sequence) : ?> <?php echo (int) $event->phase_sequence; ?><?php endif; ?><?php if ($event->clock_value !== null) : ?><div class="small text-body-secondary"><?php echo $this->escape($event->clock_value . ' ' . $event->clock_unit); ?></div><?php endif; ?></td><td><?php echo $this->escape($event->numeric_value ?? ($event->text_value ?? Text::_('JNONE'))); ?></td></tr><?php endforeach; ?>
